overriding system value
values
  (1, 1, 'ThS. Hà Trang', 'Thạc sĩ Tâm lý Lâm sàng · ĐH Xã hội Nga', 'PTSD, ADHD & LGBTQI+', 'CBT · ACT · Neurodiversity · AOP', '650K', 'Online · offline SG', null),
  (2, 2, 'ThS. Ngọc Mai', 'Thạc sĩ Tâm lý Lâm sàng', 'Tổn thương thời thơ ấu, khủng hoảng hiện sinh, lòng tự trọng thấp, rối loạn cảm xúc, vấn đề gắn bó & mối quan hệ', 'Person-Centered · CBT · MiCBT · IFS', '650K', 'Online · offline HN', null),
  (3, 3, 'ThS. Thu Thuỷ', 'Thạc sĩ Tâm lý', 'Thân chủ 20–35: mối quan hệ, childhood trauma, attachment styles, lo âu, stress, trầm cảm. Couple therapy', 'CBT · SFBT · Psychodynamic · Mindfulness', '650K', 'Chỉ online', null),
  (4, 4, 'ThS. Ly Đinh', 'Thạc sĩ Tâm lý', 'PTSD/C-PTSD, đau buồn & mất mát, trải nghiệm tuổi thơ bất lợi, trầm cảm, lo âu', 'CBT · CPT · Person-Centered · ACT · DBT', '650K', 'Chỉ online', null),
  (5, 5, 'ThS. Phương An', 'Thạc sĩ Lâm sàng · ĐH Sussex, Anh', 'Tâm lý học trường học, stress, hướng dẫn hành vi. Chuyên viên tâm lý học đường', 'CBT · MI · MBCT', '650K', 'Online · offline HN', null),
  (6, 6, 'ThS. Kim Ngân', '7 năm kinh nghiệm trị liệu', 'ADHD, sang chấn, rối loạn cảm xúc (lo âu, trầm cảm, lưỡng cực), giá trị bản thân, ranh giới', 'CBT · EFT', '650K', 'Online · offline HN', null),
  (7, 7, 'ThS. Gia Bảo', 'ThS Lâm sàng trẻ em & VTN · ĐHQG HN', 'Trầm cảm, lo âu, OCD, PTSD, rối loạn nhân cách ranh giới', 'CBT · DBT · BA', '650K', 'Online · offline HN', null),
  (8, 8, 'ThS. Mai Nguyen', 'Thạc sĩ Tâm lý', 'Vấn đề mối quan hệ (tình yêu, hôn nhân, gia đình, xã hội). Couple Hàn–Việt bằng tiếng Hàn', 'Psychoanalytic · Client-centered · Gestalt', '650K', 'Chỉ online', null),
  (9, 9, 'ThS. Minh Châu', 'Thạc sĩ Tâm lý', 'Lo âu, trầm cảm, đau buồn – tang chế, khó khăn về mối quan hệ gắn bó', 'Psychoanalysis · Adlerian · Mindfulness · Art', '750K', 'Online · offline HCM', null),
  (10, 10, 'ThS. Đức Minh', 'Trị liệu & Tư vấn · ĐH Western Sydney', 'Thân chủ 18–35: lo âu, trầm cảm, PTSD/C-PTSD, sang chấn liên thế hệ, tổn thương gắn bó. Hỗ trợ ASD, ADHD', 'Person-Centered · IFS · EFIT · MI', '650K', 'Online · offline HCM', null),
  (11, 11, 'ThS. Quỳnh Trang', 'ThS Lâm sàng · ĐHQG HN', 'Thân chủ 10–30: trầm cảm, lo âu, OCD, ám sợ xã hội, PTSD. Couple tuổi trẻ', 'CBT & các kỹ thuật lâm sàng', '600K', 'Online · offline HN', null),
  (12, 12, 'Vi Vương', 'PG Dip Tâm lý · ĐH Wrexham (Anh)', 'Tâm lý ung thư học, khủng hoảng tâm lý, bản sắc & ý nghĩa sống. 4 ngôn ngữ: Việt–Anh–Quan Thoại–Quảng Đông', 'ACT · DBT', '600K', 'Online · offline HCM', null);

select setval(
  pg_get_serial_sequence('therapists', 'id'),
  (select max(id) from therapists),
  true
);

-- BEGIN GENERATED THERAPIST PROFILES
do $$
declare
  mapped_profile_count bigint;
  invalid_profile_match_count bigint;
begin
  with profile_match_counts as (
  select
    v.expected_therapist_id,
    v.therapist_name,
    count(t.id) filter (
      where t.id = v.expected_therapist_id and t.name = v.therapist_name
    )::bigint as exact_match_count,
    count(t.id) filter (where t.id = v.expected_therapist_id)::bigint as id_match_count,
    count(t.id) filter (where t.name = v.therapist_name)::bigint as name_match_count
  from (values
  (10, 'ThS. Đức Minh', 'Nguyễn Đức Minh', 'Xin chào, tôi là Đức Minh, Thạc sĩ Tâm lý Liệu pháp và Tham vấn Tâm lý tại Western Sydney University, tốt nghiệp với thành tích Distinction và Dean’s Merit List Award. Tôi đồng thời là Nhà Tham vấn Tâm lý Thực hành được chứng nhận bởi PACFA – Liên đoàn Trị liệu và Tham vấn Tâm lý Úc, với hơn 750 giờ thực hành lâm sàng trong các môi trường tham vấn học đường và hỗ trợ tâm lý cho người lao động tại Sydney, Úc. Trong quá trình làm việc, tôi có cơ hội đồng hành cùng thanh thiếu niên và người trưởng thành đang trải qua lo âu, trầm cảm, căng thẳng, sang chấn, những tổn thương gắn bó và các khó khăn trong mối quan hệ.

Tôi đặc biệt quan tâm đến những tổn thương có thể hình thành từ các mối quan hệ quan trọng trong cuộc đời và cách chúng tiếp tục ảnh hưởng đến cách một người nhìn nhận bản thân, cảm nhận cảm xúc và kết nối với những người xung quanh. Với tôi, việc hiểu một khó khăn không chỉ nằm ở việc nhìn vào điều đang xảy ra ở hiện tại, mà còn cần đặt nó trong câu chuyện, những mối quan hệ và bối cảnh sống của mỗi người. Vì vậy, tôi sử dụng nền tảng Nhân vị Trọng tâm (Person-Centred Therapy), Hệ thống Gia đình (Family Systems Therapy), Phỏng vấn tạo Động lực (Motivational Interviewing), Liệu pháp Tập trung vào Cảm xúc (Emotionally Focused Therapy) để cùng thân chủ khám phá những nhu cầu, cảm xúc và khuôn mẫu đang ảnh hưởng đến cuộc sống của mình.

Tôi cũng đồng hành cùng các cặp đôi trong những giai đoạn nhiều thay đổi, khi khác biệt về kỳ vọng, tài chính, sự nghiệp, nuôi dạy con cái hay trách nhiệm với gia đình bắt đầu tạo ra khoảng cách giữa hai người. Tôi tin rằng mâu thuẫn không nhất thiết là dấu hiệu một mối quan hệ đã thất bại; đôi khi đó là tín hiệu cho thấy cả hai đang có những nhu cầu chưa được nhìn thấy và lắng nghe.

Với tôi, trị liệu tâm lý trước hết cần là một không gian an toàn, bảo mật và không phán xét, nơi bạn có thể thành thật với những điều khó nói, được lắng nghe và tôn trọng. Từ đó, chúng ta cùng tìm ra cách để bạn hiểu mình sâu sắc hơn, xây dựng những kết nối lành mạnh hơn và từng bước sống một cuộc đời phù hợp với điều mình thực sự coi trọng.', 'Hello, I’m Đức Minh. I hold a Master of Psychotherapy and Counselling from Western Sydney University, where I graduated with Distinction and received the Dean’s Merit List Award. I am also a practising counsellor certified by PACFA—the Psychotherapy and Counselling Federation of Australia. I have completed more than 750 hours of clinical practice in school counselling and employee mental health support settings in Sydney, Australia. In my work, I have had the opportunity to support adolescents and adults experiencing anxiety, depression, stress, trauma, attachment wounds and relationship difficulties.

I am especially interested in wounds that can develop through significant relationships in our lives and how they continue to shape the way a person sees themselves, experiences emotions and connects with others. To me, understanding a difficulty is not only about looking at what is happening in the present; it also means placing it within each person’s story, relationships and life context. I therefore draw on Person-Centred Therapy, Family Systems Therapy, Motivational Interviewing and Emotionally Focused Therapy to explore with clients the needs, emotions and patterns affecting their lives.

I also support couples through periods of significant change, when differences in expectations, finances, careers, parenting or family responsibilities begin to create distance between them. I believe conflict is not necessarily a sign that a relationship has failed; sometimes, it signals that both partners have needs that have not yet been seen or heard.

For me, psychotherapy must first and foremost be a safe, confidential and non-judgmental space where you can speak honestly about things that are difficult to say, and where you are heard and respected. From there, we can work together to help you understand yourself more deeply, build healthier connections and gradually live a life aligned with what you truly value.', null, null, true),
  (3, 'ThS. Thu Thuỷ', 'Nguyễn Thu Thủy', 'Xin chào, tôi là Thu Thuỷ, tốt nghiệp Thạc sĩ Tham vấn tâm lý tại Assumption University, Thái Lan và bắt đầu thực hành tham vấn từ năm 2023. Tôi cũng là thành viên của hiệp hội TCPA (Thailand Counseling Psychology Association). Trong quá trình làm việc, tôi có cơ hội đồng hành cùng các thân chủ trong tham vấn cá nhân, cặp đôi và nhóm, đặc biệt trong những khó khăn liên quan đến mối quan hệ, sang chấn thời thơ ấu, kiểu gắn bó và căng thẳng.

Đối với các bạn du học sinh hay Việt Kiều thì tôi càng hiểu rõ hơn vì bản thân đã từng trải qua và có những trải nghiệm để có thể đồng điệu với các bạn. Đối với các bạn sắp cưới, đã cưới và có con thì tôi lại càng hiểu hơn khi có thể đồng hành cùng bạn đi qua những cột mốc lớn trong cuộc đời.

Ngoài ra, tôi từng tham gia hỗ trợ trị liệu nhóm tại Horizon Rehab, với các chương trình như phòng ngừa tái sử dụng chất và trị liệu nhóm dựa trên nghệ thuật dành cho những người gặp khó khăn về sử dụng chất và sức khỏe tâm thần. Đồng thời, tôi đã đồng hành cùng Wabi Therapy từ những ngày đầu tiên và tiếp tục thực hành tại đây cho đến hiện tại.

Trong tham vấn, tôi kết hợp linh hoạt Psychodynamic, Gestalt, Liệu pháp Nhận thức Hành vi (CBT), Liệu pháp Hành vi Biện chứng (DBT), trị liệu dựa trên nghệ thuật và các phương pháp tiếp cận khác. Tôi không tin rằng có một phương pháp duy nhất phù hợp với tất cả mọi người vì mỗi thân chủ đều có một câu chuyện, một nhịp độ và những nhu cầu rất riêng. Vì vậy, điều tôi quan tâm là cùng bạn tìm ra cách tiếp cận phù hợp nhất với hành trình của mình.

Con đường đến với tâm lý của tôi cũng bắt đầu từ sự tò mò. Trước khi được đào tạo bài bản về Tâm lý, tôi từng tìm hiểu về Reiki (và đạt level I), Tarot, Oracle Cards (từng ứng dụng vào trong tham vấn với vẽ) và những phương pháp chữa lành tự nhiên. Những trải nghiệm đó khơi lên trong tôi nhiều câu hỏi về con người, cảm xúc và quá trình chữa lành để rồi đưa tôi đến với tâm lý học một cách khoa học và chuyên nghiệp hơn.

Với tôi, tham vấn không phải là nơi bạn được “sửa chữa” mà là một không gian để bạn có thể chậm lại, được lắng nghe và nhìn lại chính mình với sự tò mò thay vì phán xét. Chúng ta cùng nói chuyện, thảo luận về một chủ đề nào đó. Không cần gấp gáp, chầm chậm và từ tốn khai mở nút thắt trong lòng. Từ đó, bạn có thể hiểu mình hơn, nhận ra những điều mình thực sự cần và có thêm lựa chọn cho cách mình muốn sống, yêu thương và kết nối với người khác.', 'Hello, I’m Thu Thuỷ. I earned a Master’s degree in Counselling Psychology from Assumption University in Thailand and began practising counselling in 2023. I am also a member of the Thailand Counseling Psychology Association (TCPA). Through my work, I have had the opportunity to support clients in individual, couples and group counselling, particularly with difficulties involving relationships, childhood trauma, attachment patterns and stress.

I have an especially personal understanding of international students and overseas Vietnamese because I have been through similar experiences and can relate to what you may be going through. I also understand those who are preparing for marriage, are married or have children, and can accompany you through these major milestones in life.

I have also helped facilitate group therapy at Horizon Rehab, including relapse-prevention programmes and art-based group therapy for people experiencing substance-use and mental health difficulties. At the same time, I have been with Wabi Therapy since its earliest days and continue to practise here today.

In counselling, I flexibly integrate Psychodynamic and Gestalt approaches, Cognitive Behavioural Therapy (CBT), Dialectical Behaviour Therapy (DBT), art-based therapy and other approaches. I do not believe that a single method suits everyone, because every client has their own story, pace and individual needs. What matters to me, therefore, is working with you to find the approach best suited to your journey.

My path into psychology also began with curiosity. Before receiving formal training in psychology, I explored Reiki (reaching Level I), Tarot, Oracle Cards—which I once incorporated into counselling alongside drawing—and natural healing practices. These experiences prompted many questions for me about people, emotions and the healing process, ultimately leading me toward a more scientific and professional engagement with psychology.

For me, counselling is not a place where you are “fixed,” but a space where you can slow down, be heard and look at yourself with curiosity rather than judgment. We talk together and explore what is on your mind. There is no need to rush; slowly and gently, we can begin to loosen the knots within. From there, you can understand yourself better, recognise what you truly need and discover more choices in how you want to live, love and connect with others.', null, null, true),
  (2, 'ThS. Ngọc Mai', 'Nguyễn Ngọc Mai', 'Xin chào, tôi là Ngọc Mai, Thạc sĩ Tâm lý học chuyên ngành Tâm lý lâm sàng và Cử nhân Tâm lý học chuyên ngành Tham vấn tâm lý tại Trường Đại học Khoa học Xã hội và Nhân văn, Đại học Quốc gia Hà Nội. Tôi bắt đầu thực hành tham vấn và trị liệu tâm lý từ năm 2020, và trong quá trình làm việc, tôi chủ yếu đồng hành cùng những người trẻ từ 18–35 tuổi đang tìm cách hiểu mình hơn, điều chỉnh cảm xúc, xây dựng những mối quan hệ lành mạnh và tìm kiếm một hướng đi phù hợp cho cuộc sống.

Tôi có kinh nghiệm đồng hành với những khó khăn liên quan đến tổn thương và trải nghiệm thời thơ ấu, căng thẳng, lo âu, trầm cảm, lòng tự trọng, tự chỉ trích, khủng hoảng và cảm giác mất phương hướng. Bên cạnh đó, tôi cũng làm việc với những vấn đề về gắn bó, các khuôn mẫu lặp lại trong tình yêu và các mối quan hệ gia đình, cũng như những áp lực trong học tập, công việc, định hướng nghề nghiệp và khủng hoảng sự nghiệp. Trong quá trình trị liệu, tôi linh hoạt kết hợp Trị liệu Nhân vị trọng tâm, Trị liệu Nhận thức Hành vi (CBT), Trị liệu Nhận thức Hành vi kết hợp Chánh niệm (MiCBT) và Hệ thống Gia đình Nội tâm (IFS), tùy thuộc vào nhu cầu, mục tiêu và nhịp độ riêng của từng thân chủ.

Tôi tin rằng bạn là người hiểu rõ nhất cuộc sống của mình và là người quyết định mình muốn đi về đâu. Nếu hành trình ấy giống như việc đi qua một đêm tối, tôi muốn mình giống như một chiếc đèn pin – không đi thay bạn, không quyết định con đường thay bạn, mà giúp bạn nhìn rõ hơn những gì đang ở phía trước.

Với tôi, tìm đến một nhà tâm lý không có nghĩa là bạn yếu đuối hay không thể tự giải quyết vấn đề. Đôi khi, đó chính là một cách để bạn dũng cảm đối diện với những điều mình đã cố gắng chịu đựng một mình quá lâu. Trị liệu không phải là hành trình để trở thành một con người hoàn toàn khác, mà là quá trình hiểu mình hơn, học cách chấp nhận cả những phần dễ tổn thương, tìm lại những nguồn lực vốn có và từng bước xây dựng một cuộc sống phù hợp hơn với chính mình. Tôi hy vọng quá trình đồng hành của chúng ta sẽ giúp bạn không chỉ vượt qua một giai đoạn khó khăn, mà còn dần học được cách trở thành người có thể lắng nghe, thấu hiểu và đồng hành cùng chính mình.', 'Hello, I’m Ngọc Mai. I hold a Master’s degree in Psychology, specialising in Clinical Psychology, and a Bachelor’s degree in Psychology, specialising in Counselling Psychology, from the University of Social Sciences and Humanities, Vietnam National University, Hanoi. I began practising counselling and psychotherapy in 2020. In my work, I primarily support young adults aged 18–35 who are seeking to understand themselves better, regulate their emotions, build healthy relationships and find a direction in life that feels right for them.

I have experience supporting people with difficulties related to childhood wounds and experiences, stress, anxiety, depression, self-esteem, self-criticism, crises and feeling lost. I also work with attachment concerns, recurring patterns in romantic and family relationships, and pressures related to study, work, career direction and career crises. In therapy, I flexibly integrate Person-Centred Therapy, Cognitive Behavioural Therapy (CBT), Mindfulness-integrated Cognitive Behaviour Therapy (MiCBT) and Internal Family Systems (IFS), depending on each client’s needs, goals and individual pace.

I believe that you understand your own life best and that you are the one who decides where you want to go. If that journey is like walking through a dark night, I would like to be like a flashlight for you—not to walk the journey or choose the path on your behalf, but to help illuminate what lies ahead.

To me, seeking support from a psychologist does not mean that you are weak or unable to solve your own problems. Sometimes, it is a way of courageously facing what you have tried to endure alone for too long. Therapy is not a journey toward becoming a completely different person; it is a process of understanding yourself more deeply, learning to accept your vulnerable parts, reconnecting with the resources already within you and gradually building a life that fits who you are. I hope our work together will help you not only move through a difficult period, but also gradually learn to become someone who can listen to, understand and support yourself.', null, null, true),
  (9, 'ThS. Minh Châu', 'Minh Châu', 'Xin chào, tôi là Minh Châu, Thạc sĩ Tâm lý học tại Trường Đại học Sư phạm Thành phố Hồ Chí Minh, với 7 năm kinh nghiệm thực hành trong lĩnh vực chăm sóc sức khỏe tâm thần. Trong quá trình làm việc, tôi có cơ hội đồng hành cùng nhiều thân chủ đang trải qua những khó khăn về lo âu, trầm cảm, đau buồn và mất mát, những vấn đề trong mối quan hệ gắn bó cũng như những ảnh hưởng còn kéo dài từ các trải nghiệm bất lợi thời thơ ấu.

Tôi đặc biệt quan tâm đến cách những trải nghiệm trong quá khứ có thể tiếp tục hiện diện trong đời sống hiện tại của mỗi người – qua cách chúng ta nhìn nhận bản thân, cảm nhận và điều hòa cảm xúc, xây dựng các mối quan hệ hay phản ứng trước những tình huống quen thuộc. Vì vậy, trong quá trình đồng hành, tôi không chỉ quan tâm đến điều đang khiến bạn khó khăn ở hiện tại, mà còn cùng bạn từ từ khám phá những câu chuyện, nhu cầu và trải nghiệm phía sau những điều ấy.

Về phương pháp, tôi thực hành theo hướng tích hợp, lấy nền tảng từ Phân tâm học (Psychoanalytic) và linh hoạt kết hợp các góc nhìn từ Tâm lý học Adler (Adlerian), thực hành Chú tâm (Mindfulness), sử dụng nghệ thuật như công cụ biểu đạt (art-based methods). Tôi tin rằng mỗi người có một câu chuyện riêng, vì vậy trị liệu cũng cần được điều chỉnh theo nhu cầu, khả năng và nhịp độ của từng thân chủ thay vì áp dụng một công thức giống nhau cho tất cả.

Với tôi, tham vấn tâm lý trước hết là một mối quan hệ an toàn, là không gian lắng nghe thấu đáo và không phán xét để bạn chậm lại, gọi tên và khám phá bất kỳ khía cạnh nào liên quan nhất đến sự an lành của mình — kể cả những bối rối hay nỗi đau sâu kín chưa thể gọi tên. Tôi mong muốn đồng hành cùng bạn để từng bước thấu hiểu, chấp nhận chính bản thân và sẵn sàng kết nối lành mạnh với cuộc sống.', 'Hello, I’m Minh Châu. I hold a Master’s degree in Psychology from Ho Chi Minh City University of Education and have seven years of practical experience in mental health care. In my work, I have had the opportunity to support many clients experiencing anxiety, depression, grief and loss, difficulties in attachment relationships, and the lasting effects of adverse childhood experiences.

I am especially interested in how past experiences can remain present in each person’s life today—through the ways we see ourselves, experience and regulate emotions, build relationships, or respond to familiar situations. In our work together, I therefore pay attention not only to what is causing you difficulty in the present, but also join you in gradually exploring the stories, needs and experiences behind it.

My practice is integrative, grounded in Psychoanalytic approaches and flexibly incorporating perspectives from Adlerian Psychology, Mindfulness practice and art-based methods as tools for expression. I believe that every person has their own story, so therapy needs to be adapted to each client’s needs, capacities and pace rather than following the same formula for everyone.

For me, psychological counselling is first and foremost a safe relationship: a space of attentive, non-judgmental listening where you can slow down, name and explore whatever feels most relevant to your well-being—including confusion or deeply held pain that cannot yet be named. I hope to accompany you as you gradually understand and accept yourself, and become ready to connect with life in healthier ways.', null, null, true),
  (4, 'ThS. Ly Đinh', 'Đinh Y Ly', 'Xin chào.

Tôi là Ly, là một thạc sĩ tâm lí (lâm sàng) được đào tạo từ trường ĐH KHXH&NV, ĐHQG Hà Nội với hơn 6 năm kinh nghiệm làm việc trong lĩnh vực tâm lí, bao gồm cung cấp dịch vụ đánh giá, tham vấn và trị liệu tâm lí cho các khách hàng cá nhân.

Từ những trải nghiệm cá nhân kết hợp với quá trình học tập, nghiên cứu và thực hành, tôi đã xác định và phát triển chuyên môn theo định hướng làm việc với các thân chủ là người trưởng thành mang những nỗi đau từ các trải nghiệm bất lợi, tổn thương, sang chấn thời thơ ấu. Các tổn thương đó có thể biểu hiện thành những rối loạn như trầm cảm, lo âu, cũng có thể ảnh hưởng đến lòng tự trọng, cách mỗi người nhìn nhận và đánh giá bản thân, lối hành xử và tương tác trong các mối quan hệ với người khác. Vì vậy, đây không phải một quá trình dễ dàng và nhanh chóng, nhưng tôi tin rằng mình đủ kiên nhẫn, kiến thức và trải nghiệm để đồng hành cùng bạn đi đến cuối hành trình khám phá và tự hàn gắn này.

Trong quá trình làm việc, tôi sử dụng kết hợp liệu pháp CBT với các triết lí và kĩ thuật về thân chủ trọng tâm, chánh niệm, chấp nhận và cam kết (ACT). Tuy vậy, đối với tôi, trị liệu tâm lí không chỉ là thực hành các liệu pháp hay kĩ thuật, mà đó là quá trình một người mở rộng vùng trải nghiệm của mình, thêm vào đó các trải nghiệm tích cực như được chấp nhận vô điều kiện, được lắng nghe, được nhìn thấy, được sự an toàn, được thử, được sai, được thử lại... Từ đó, bạn có thể dấn thân vào cuộc sống và các mối quan hệ, nhìn nhận các giá trị của bản thân, lấy lại sự tự chủ, tự do, niềm tin vào chính mình để hướng tới một cuộc sống bình an, độc lập.

Ngoài ra, tôi cũng đồng hành và hỗ trợ những người đang trải qua đau buồn và mất mát – dù đó là sự ra đi của người thân, thú cưng, chia tay mối quan hệ hay việc phải đối diện với bệnh tật và những thay đổi lớn trong cuộc sống. Đây đều là những trải nghiệm không dễ dàng, và bạn hoàn toàn có quyền lựa chọn không phải trải qua chúng một mình. Các phiên làm việc đều là không gian an toàn để bạn có thể từng bước nhìn nhận và xử lý những cảm xúc bạn đang trải qua, giải tỏa những điều còn dồn nén, thích nghi và dần tìm lại sự cân bằng trong cuộc sống.

Thực hành của tôi đều dựa trên các nguyên tắc đạo đức nghề nghiệp, sự tôn trọng và tin tưởng đối với mỗi thân chủ của mình. Mọi hoạt động hỗ trợ đều hướng đến lợi ích, nhu cầu và sự an toàn của chính bạn.', 'Hello.

I’m Ly. I hold a Master’s degree in Psychology, with a clinical focus, from the University of Social Sciences and Humanities, Vietnam National University, Hanoi. I have more than six years of experience in psychology, including providing psychological assessment, counselling and therapy services to individual clients.

Through my personal experiences alongside study, research and practice, I have shaped and developed my professional focus around working with adult clients who carry pain from adverse experiences, wounds and childhood trauma. These wounds may manifest as conditions such as depression and anxiety, and may also affect self-esteem, how a person sees and evaluates themselves, and how they behave and interact in relationships with others. This is therefore neither an easy nor a quick process, but I believe I have the patience, knowledge and experience to accompany you through to the end of this journey of exploration and self-healing.

In my work, I combine CBT with person-centred principles and techniques, mindfulness, and Acceptance and Commitment Therapy (ACT). For me, however, psychotherapy is not only about applying therapies or techniques. It is a process through which a person broadens their range of experience by making room for positive experiences: being accepted unconditionally, being heard, being seen, feeling safe, being allowed to try, to make mistakes and to try again... From there, you can engage more fully with life and relationships, recognise your own values, and regain autonomy, freedom and confidence in yourself as you move toward a peaceful, independent life.

I also accompany and support people experiencing grief and loss—whether the death of a loved one or pet, the end of a relationship, illness, or major changes in life. None of these experiences is easy, and you have every right to choose not to go through them alone. Each session is a safe space where you can gradually acknowledge and process the emotions you are experiencing, release what has remained pent up, adapt and slowly regain balance in your life.

My practice is grounded in professional ethical principles, as well as respect for and trust in every client. All support is centred on your own well-being, needs and safety.', null, null, true),
  (11, 'ThS. Quỳnh Trang', 'Ngọ Quỳnh Trang', 'Mình là Quỳnh Trang, Thạc sĩ Tâm lý học lâm sàng, chuyên ngành Tâm lý học lâm sàng Trẻ em và Vị thành niên, đồng thời có nền tảng Cử nhân Tâm lý học, chuyên ngành Tâm lý học Tham vấn. Trong 3 năm làm việc trong lĩnh vực tâm lý, mình có cơ hội đồng hành cùng nhiều thân chủ đang trải qua căng thẳng, lo âu, trầm cảm, những ảnh hưởng liên quan đến sang chấn và các khó khăn trong mối quan hệ cặp đôi. Mình đặc biệt quan tâm đến việc giúp thân chủ hiểu hơn về những gì đang diễn ra bên trong mình, thay vì chỉ cố gắng loại bỏ một triệu chứng hay giải quyết nhanh một vấn đề. Trong quá trình làm việc, mình lựa chọn cách tiếp cận dựa trên sự thấu cảm, tôn trọng và chấp nhận vô điều kiện theo tinh thần thân chủ trọng tâm. Tùy vào nhu cầu và mục tiêu của mỗi người, mình được đào tạo và ứng dụng Liệu pháp Nhận thức Hành vi (CBT), đồng thời tích hợp các kỹ thuật điều hòa cảm xúc từ Chánh niệm và Liệu pháp Chấp nhận và Cam kết (ACT). Mình tin rằng trị liệu không phải là nơi therapist đưa ra câu trả lời thay cho thân chủ, mà là một không gian đủ an toàn để thân chủ có thể chậm lại, nhìn lại và từng bước tìm ra câu trả lời phù hợp với chính mình. Có những lúc chúng ta cần một người đồng hành để hiểu điều gì đang xảy ra; có những lúc cần một người giúp mình học cách bước qua một đoạn đường khó; và cũng có lúc điều quan trọng nhất là nhận ra mình đã đủ vững vàng để tự bước tiếp.', 'I’m Quỳnh Trang. I hold a Master’s degree in Clinical Psychology, specialising in Child and Adolescent Clinical Psychology, as well as a Bachelor’s degree in Psychology, specialising in Counselling Psychology. During my three years working in psychology, I have had the opportunity to support many clients experiencing stress, anxiety, depression, trauma-related effects and difficulties in couple relationships. I am especially interested in helping clients understand more about what is happening within them, rather than simply trying to remove a symptom or quickly solve a problem. In my work, I take an approach grounded in empathy, respect and unconditional acceptance, in keeping with person-centred principles. Depending on each person’s needs and goals, I am trained in and apply Cognitive Behavioural Therapy (CBT), while also integrating emotion-regulation techniques from Mindfulness and Acceptance and Commitment Therapy (ACT). I believe therapy is not a place where the therapist gives clients answers, but a space safe enough for clients to slow down, reflect and gradually find answers that fit who they are. Sometimes we need a companion to help us understand what is happening; sometimes we need someone to help us learn how to make it through a difficult stretch of the road; and sometimes what matters most is recognising that we are steady enough to continue on our own.', 'Mình nghĩ bản thân giống như cây gậy, thân chủ có thể cần đến cây gậy để đi qua một đoạn đường dốc và trắc trở một cách vững vàng hơn, thân chủ cũng có thể dùng cây gậy để dò dẫm xem liệu con đường mình định bước có gì nguy hiểm không và đương nhiên, sẽ có đoạn đường, thân chủ không cần đến cây gậy nữa mà có thể tự đi một cách vững vàng, an toàn. Và mình ở đây, nếu bạn cần 1 chiếc gậy.', 'I think of myself as a walking stick. A client may need the stick to move more steadily through a steep and difficult stretch; they may also use it to feel out whether the path ahead holds any danger. And of course, there will come a part of the journey when they no longer need the stick and can walk on safely and steadily by themselves. I am here if you need a walking stick.', true),
  (5, 'ThS. Phương An', 'An Nguyễn Như Phương', 'Xin chào, tôi là Phương An, Thạc sĩ Tâm lý học Lâm sàng và Sức khỏe Tâm thần tại University of Sussex, Vương quốc Anh, và Cử nhân Tâm lý học tại Trường Đại học Sư phạm Hà Nội. Tôi có 4 năm kinh nghiệm trong lĩnh vực tâm lý học trường học, tham vấn và hỗ trợ sức khỏe tinh thần, với cơ hội đồng hành cùng trẻ em, thanh thiếu niên, người trưởng thành và gia đình trong nhiều bối cảnh khác nhau.

Trong công việc, tôi đặc biệt quan tâm đến những khó khăn liên quan đến lo âu, căng thẳng, điều chỉnh cảm xúc, lòng tự trọng, các mối quan hệ, học tập và quá trình thích nghi với những thay đổi trong cuộc sống. Bên cạnh việc đồng hành trực tiếp cùng thân chủ, tôi cũng hỗ trợ cha mẹ hiểu hơn về cảm xúc và hành vi của con, từ đó tìm ra những cách giao tiếp và đồng hành phù hợp hơn. Kinh nghiệm trong môi trường học đường giúp tôi nhìn nhận những khó khăn tâm lý trong mối liên hệ với nhiều yếu tố xung quanh một người, bao gồm gia đình, nhà trường và các mối quan hệ.

Trong tham vấn và trị liệu, tôi sử dụng Liệu pháp Nhận thức – Hành vi (CBT), Liệu pháp Chấp nhận và Cam kết (ACT), chánh niệm và một số kỹ thuật từ DBT. Tôi linh hoạt kết hợp các phương pháp dựa trên nhu cầu, mục tiêu và nhịp độ của từng thân chủ. Tôi tin rằng không có một công thức chung cho hành trình của mỗi người; điều quan trọng là cùng tìm ra một cách tiếp cận phù hợp và xây dựng một không gian đủ an toàn để thân chủ có thể thành thật với chính mình.

Tôi tin rằng mỗi người, dù là một đứa trẻ đang học cách gọi tên cảm xúc, một người trẻ đang loay hoay với những lựa chọn của mình, hay một người trưởng thành đang tìm lại hướng đi, đều xứng đáng được lắng nghe và thấu hiểu. Với tôi, trị liệu không phải là việc đưa ra câu trả lời thay bạn, mà là cùng bạn xây dựng một mối quan hệ đủ an toàn để bạn có thể là chính mình, hiểu bản thân sâu sắc hơn và từng bước tìm ra cách sống phù hợp với những điều thực sự có ý nghĩa với mình.', 'Hello, I’m Phương An. I hold a Master’s degree in Clinical Psychology and Mental Health from the University of Sussex in the United Kingdom, and a Bachelor’s degree in Psychology from Hanoi National University of Education. I have four years of experience in school psychology, counselling and mental health support, with opportunities to work alongside children, adolescents, adults and families across a range of settings.

In my work, I am especially interested in difficulties related to anxiety, stress, emotion regulation, self-esteem, relationships, learning and adapting to changes in life. Alongside working directly with clients, I also help parents better understand their children’s emotions and behaviours so they can find more suitable ways to communicate with and support them. My experience in school settings helps me understand psychological difficulties in relation to the many factors surrounding a person, including family, school and relationships.

In counselling and therapy, I use Cognitive Behavioural Therapy (CBT), Acceptance and Commitment Therapy (ACT), mindfulness and selected DBT techniques. I flexibly integrate these approaches according to each client’s needs, goals and pace. I believe there is no single formula for every person’s journey; what matters is finding a suitable approach together and building a space safe enough for clients to be honest with themselves.

I believe that everyone—whether a child learning to name their emotions, a young person wrestling with their choices, or an adult trying to find direction again—deserves to be heard and understood. For me, therapy is not about giving you answers, but about building a relationship with you that is safe enough for you to be yourself, understand yourself more deeply and gradually find a way of living aligned with what truly matters to you.', null, null, true),
  (7, 'ThS. Gia Bảo', 'Trần Gia Bảo', 'Xin chào, tôi là Gia Bảo, Thạc sĩ Tâm lý học tại Trường Đại học Giáo dục, Đại học Quốc gia Hà Nội, sau khi tốt nghiệp Cử nhân Tâm lý học tại Trường Đại học Sư phạm Hà Nội. Tôi có 4 năm kinh nghiệm trong lĩnh vực can thiệp các khó khăn và rối loạn hướng nội, đặc biệt là trầm cảm, lo âu và rối loạn nhân cách ranh giới. Bên cạnh thực hành, tôi cũng tham gia giảng dạy các khóa học chuyên môn về tâm lý học.

Trong quá trình làm việc, tôi sử dụng Liệu pháp Nhận thức Hành vi (CBT) làm phương pháp chính, kết hợp một số kỹ thuật từ Liệu pháp Hành vi Biện chứng (DBT) tùy theo nhu cầu và mục tiêu của từng thân chủ. Tôi tin rằng trị liệu không chỉ nhằm giảm bớt những triệu chứng đang gây khó khăn, mà còn giúp thân chủ hiểu mình hơn và từng bước có khả năng tự ứng phó với những thử thách trong cuộc sống.

Tôi tin rằng mục tiêu sâu xa nhất của trị liệu là giúp thân chủ trở thành chuyên gia tâm lý của chính mình – người có thể nhận biết, thấu hiểu và tự mình ứng phó với những khó khăn trong cuộc sống.

Vì vậy, tôi mong muốn tạo ra một không gian an toàn, nơi bạn có thể được lắng nghe và chia sẻ mà không sợ bị phán xét. Tôi sẽ cùng bạn khám phá những điều đang diễn ra, nhận diện nguồn lực của bản thân và từng bước tìm ra cách phù hợp để chăm sóc sức khỏe tinh thần của mình.', 'Hello, I’m Gia Bảo. I hold a Master’s degree in Psychology from the University of Education, Vietnam National University, Hanoi, after earning a Bachelor’s degree in Psychology from Hanoi National University of Education. I have four years of experience in interventions for internalising difficulties and disorders, particularly depression, anxiety and borderline personality disorder. Alongside my practice, I also teach professional courses in psychology.

In my work, I primarily use Cognitive Behavioural Therapy (CBT), integrating selected techniques from Dialectical Behaviour Therapy (DBT) according to each client’s needs and goals. I believe therapy is not only intended to ease symptoms that are causing difficulty, but also to help clients understand themselves better and gradually develop the ability to cope independently with life’s challenges.

I believe the deepest goal of therapy is to help clients become experts in their own psychological lives—able to recognise and understand their difficulties and cope with life’s challenges independently.

I therefore hope to create a safe space where you can be heard and share without fear of judgment. I will explore with you what is happening, help you recognise your own resources and gradually find suitable ways to care for your mental health.', null, null, true),
  (6, 'ThS. Kim Ngân', 'Nguyễn Thị Kim Ngân', 'Xin chào, tôi là Kim Ngân, Thạc sĩ Tâm lý học theo định hướng ứng dụng tại Trường Đại học Khoa học Xã hội và Nhân văn, Đại học Quốc gia Hà Nội, với 7 năm học tập và thực hành trong lĩnh vực sức khỏe tâm thần. Trong quá trình làm việc, tôi có cơ hội đồng hành cùng những người đang trải qua sang chấn, những trải nghiệm khó khăn thời thơ ấu và các vấn đề liên quan đến rối loạn cảm xúc như lo âu, trầm cảm, lưỡng cực, cũng như những khó khăn về giá trị bản thân, ranh giới, các mối quan hệ và sức khỏe sinh sản.

Tôi đặc biệt quan tâm đến cách những trải nghiệm trong quá khứ có thể để lại dấu ấn trong cách mỗi người nhìn nhận bản thân, cảm nhận cảm xúc và xây dựng mối quan hệ với những người xung quanh. Vì vậy, trong quá trình trị liệu, tôi mong muốn cùng thân chủ từ từ khám phá câu chuyện của chính mình, hiểu hơn về những điều đã hình thành nên con người hiện tại và tìm lại những nguồn lực bên trong để có thể sống theo cách phù hợp hơn với bản thân.

Trong thực hành, tôi sử dụng linh hoạt Liệu pháp Nhận thức Hành vi (CBT), Chánh niệm (Mindfulness) và Liệu pháp Hành vi Biện chứng (DBT), tùy thuộc vào nhu cầu, mục tiêu và nhịp độ của từng thân chủ. Với tôi, trị liệu không phải là một quá trình buộc chúng ta phải trở thành một phiên bản hoàn toàn khác, mà là cơ hội để hiểu mình sâu sắc hơn, học cách ở cùng những phần dễ tổn thương và từng bước xây dựng khả năng chăm sóc chính mình.

Tôi tin rằng mỗi người đều có khả năng hồi phục, ngay cả khi đang ở trong những giai đoạn khó khăn nhất. Tôi mong muốn tạo ra một không gian an toàn và đủ dịu dàng để bạn có thể được lắng nghe, được thấu hiểu và có thời gian phát triển theo nhịp độ của riêng mình. Có thể hành trình ấy bắt đầu từ một đêm tối, nhưng tôi tin rằng ở đâu đó bên trong mỗi người vẫn luôn có một hạt mầm đang chờ được chăm sóc để một ngày có thể nở hoa.', 'Hello, I’m Kim Ngân. I hold a practice-oriented Master’s degree in Psychology from the University of Social Sciences and Humanities, Vietnam National University, Hanoi, and have spent seven years studying and practising in the mental health field. In my work, I have had the opportunity to support people experiencing trauma, difficult childhood experiences and concerns related to emotional disorders such as anxiety, depression and bipolar disorder, as well as difficulties involving self-worth, boundaries, relationships and reproductive health.

I am especially interested in how past experiences can leave their mark on the way each person sees themselves, experiences emotions and builds relationships with those around them. In therapy, I therefore hope to join clients in gradually exploring their own stories, understanding more about what has shaped who they are today, and reconnecting with their inner resources so they can live in ways that fit them more closely.

In my practice, I flexibly use Cognitive Behavioural Therapy (CBT), Mindfulness and Dialectical Behaviour Therapy (DBT), depending on each client’s needs, goals and pace. For me, therapy is not a process that forces us to become a completely different version of ourselves, but an opportunity to understand ourselves more deeply, learn to be with our vulnerable parts and gradually build our capacity for self-care.

I believe everyone has the capacity to recover, even during the most difficult times. I hope to create a space that is safe and gentle enough for you to be heard and understood, and to have time to grow at your own pace. That journey may begin in darkness, but I believe that somewhere within each person there is always a seed waiting to be nurtured so that one day it can bloom.', 'Nảy mầm trong đêm tối và nở hoa dưới ánh mặt trời.', 'Sprouting in the darkness and blooming in the sunlight.', true)
  ) as v(expected_therapist_id, therapist_name, full_name, bio_vi, bio_en, quote_vi, quote_en, is_published)
  left join therapists t
    on t.id = v.expected_therapist_id or t.name = v.therapist_name
  group by v.expected_therapist_id, v.therapist_name
)
select
  coalesce(sum(exact_match_count), 0)::bigint,
  count(*) filter (
    where exact_match_count <> 1 or id_match_count <> 1 or name_match_count <> 1
  )::bigint
into mapped_profile_count, invalid_profile_match_count
from profile_match_counts;

  if mapped_profile_count <> 9
    or invalid_profile_match_count > 0
  then
    raise exception
      'Expected exactly 9 therapist profile ID/name mappings; found % mapping rows and % invalid mappings',
      mapped_profile_count,
      invalid_profile_match_count;
  end if;
end
$$;

insert into therapist_profiles (
  therapist_id, full_name, bio_vi, bio_en,
  quote_vi, quote_en, is_published, updated_at
)
select
  t.id, v.full_name, v.bio_vi, v.bio_en,
  v.quote_vi, v.quote_en, v.is_published, now()
from (values
  (10, 'ThS. Đức Minh', 'Nguyễn Đức Minh', 'Xin chào, tôi là Đức Minh, Thạc sĩ Tâm lý Liệu pháp và Tham vấn Tâm lý tại Western Sydney University, tốt nghiệp với thành tích Distinction và Dean’s Merit List Award. Tôi đồng thời là Nhà Tham vấn Tâm lý Thực hành được chứng nhận bởi PACFA – Liên đoàn Trị liệu và Tham vấn Tâm lý Úc, với hơn 750 giờ thực hành lâm sàng trong các môi trường tham vấn học đường và hỗ trợ tâm lý cho người lao động tại Sydney, Úc. Trong quá trình làm việc, tôi có cơ hội đồng hành cùng thanh thiếu niên và người trưởng thành đang trải qua lo âu, trầm cảm, căng thẳng, sang chấn, những tổn thương gắn bó và các khó khăn trong mối quan hệ.

Tôi đặc biệt quan tâm đến những tổn thương có thể hình thành từ các mối quan hệ quan trọng trong cuộc đời và cách chúng tiếp tục ảnh hưởng đến cách một người nhìn nhận bản thân, cảm nhận cảm xúc và kết nối với những người xung quanh. Với tôi, việc hiểu một khó khăn không chỉ nằm ở việc nhìn vào điều đang xảy ra ở hiện tại, mà còn cần đặt nó trong câu chuyện, những mối quan hệ và bối cảnh sống của mỗi người. Vì vậy, tôi sử dụng nền tảng Nhân vị Trọng tâm (Person-Centred Therapy), Hệ thống Gia đình (Family Systems Therapy), Phỏng vấn tạo Động lực (Motivational Interviewing), Liệu pháp Tập trung vào Cảm xúc (Emotionally Focused Therapy) để cùng thân chủ khám phá những nhu cầu, cảm xúc và khuôn mẫu đang ảnh hưởng đến cuộc sống của mình.

Tôi cũng đồng hành cùng các cặp đôi trong những giai đoạn nhiều thay đổi, khi khác biệt về kỳ vọng, tài chính, sự nghiệp, nuôi dạy con cái hay trách nhiệm với gia đình bắt đầu tạo ra khoảng cách giữa hai người. Tôi tin rằng mâu thuẫn không nhất thiết là dấu hiệu một mối quan hệ đã thất bại; đôi khi đó là tín hiệu cho thấy cả hai đang có những nhu cầu chưa được nhìn thấy và lắng nghe.

Với tôi, trị liệu tâm lý trước hết cần là một không gian an toàn, bảo mật và không phán xét, nơi bạn có thể thành thật với những điều khó nói, được lắng nghe và tôn trọng. Từ đó, chúng ta cùng tìm ra cách để bạn hiểu mình sâu sắc hơn, xây dựng những kết nối lành mạnh hơn và từng bước sống một cuộc đời phù hợp với điều mình thực sự coi trọng.', 'Hello, I’m Đức Minh. I hold a Master of Psychotherapy and Counselling from Western Sydney University, where I graduated with Distinction and received the Dean’s Merit List Award. I am also a practising counsellor certified by PACFA—the Psychotherapy and Counselling Federation of Australia. I have completed more than 750 hours of clinical practice in school counselling and employee mental health support settings in Sydney, Australia. In my work, I have had the opportunity to support adolescents and adults experiencing anxiety, depression, stress, trauma, attachment wounds and relationship difficulties.

I am especially interested in wounds that can develop through significant relationships in our lives and how they continue to shape the way a person sees themselves, experiences emotions and connects with others. To me, understanding a difficulty is not only about looking at what is happening in the present; it also means placing it within each person’s story, relationships and life context. I therefore draw on Person-Centred Therapy, Family Systems Therapy, Motivational Interviewing and Emotionally Focused Therapy to explore with clients the needs, emotions and patterns affecting their lives.

I also support couples through periods of significant change, when differences in expectations, finances, careers, parenting or family responsibilities begin to create distance between them. I believe conflict is not necessarily a sign that a relationship has failed; sometimes, it signals that both partners have needs that have not yet been seen or heard.

For me, psychotherapy must first and foremost be a safe, confidential and non-judgmental space where you can speak honestly about things that are difficult to say, and where you are heard and respected. From there, we can work together to help you understand yourself more deeply, build healthier connections and gradually live a life aligned with what you truly value.', null, null, true),
  (3, 'ThS. Thu Thuỷ', 'Nguyễn Thu Thủy', 'Xin chào, tôi là Thu Thuỷ, tốt nghiệp Thạc sĩ Tham vấn tâm lý tại Assumption University, Thái Lan và bắt đầu thực hành tham vấn từ năm 2023. Tôi cũng là thành viên của hiệp hội TCPA (Thailand Counseling Psychology Association). Trong quá trình làm việc, tôi có cơ hội đồng hành cùng các thân chủ trong tham vấn cá nhân, cặp đôi và nhóm, đặc biệt trong những khó khăn liên quan đến mối quan hệ, sang chấn thời thơ ấu, kiểu gắn bó và căng thẳng.

Đối với các bạn du học sinh hay Việt Kiều thì tôi càng hiểu rõ hơn vì bản thân đã từng trải qua và có những trải nghiệm để có thể đồng điệu với các bạn. Đối với các bạn sắp cưới, đã cưới và có con thì tôi lại càng hiểu hơn khi có thể đồng hành cùng bạn đi qua những cột mốc lớn trong cuộc đời.

Ngoài ra, tôi từng tham gia hỗ trợ trị liệu nhóm tại Horizon Rehab, với các chương trình như phòng ngừa tái sử dụng chất và trị liệu nhóm dựa trên nghệ thuật dành cho những người gặp khó khăn về sử dụng chất và sức khỏe tâm thần. Đồng thời, tôi đã đồng hành cùng Wabi Therapy từ những ngày đầu tiên và tiếp tục thực hành tại đây cho đến hiện tại.

Trong tham vấn, tôi kết hợp linh hoạt Psychodynamic, Gestalt, Liệu pháp Nhận thức Hành vi (CBT), Liệu pháp Hành vi Biện chứng (DBT), trị liệu dựa trên nghệ thuật và các phương pháp tiếp cận khác. Tôi không tin rằng có một phương pháp duy nhất phù hợp với tất cả mọi người vì mỗi thân chủ đều có một câu chuyện, một nhịp độ và những nhu cầu rất riêng. Vì vậy, điều tôi quan tâm là cùng bạn tìm ra cách tiếp cận phù hợp nhất với hành trình của mình.

Con đường đến với tâm lý của tôi cũng bắt đầu từ sự tò mò. Trước khi được đào tạo bài bản về Tâm lý, tôi từng tìm hiểu về Reiki (và đạt level I), Tarot, Oracle Cards (từng ứng dụng vào trong tham vấn với vẽ) và những phương pháp chữa lành tự nhiên. Những trải nghiệm đó khơi lên trong tôi nhiều câu hỏi về con người, cảm xúc và quá trình chữa lành để rồi đưa tôi đến với tâm lý học một cách khoa học và chuyên nghiệp hơn.

Với tôi, tham vấn không phải là nơi bạn được “sửa chữa” mà là một không gian để bạn có thể chậm lại, được lắng nghe và nhìn lại chính mình với sự tò mò thay vì phán xét. Chúng ta cùng nói chuyện, thảo luận về một chủ đề nào đó. Không cần gấp gáp, chầm chậm và từ tốn khai mở nút thắt trong lòng. Từ đó, bạn có thể hiểu mình hơn, nhận ra những điều mình thực sự cần và có thêm lựa chọn cho cách mình muốn sống, yêu thương và kết nối với người khác.', 'Hello, I’m Thu Thuỷ. I earned a Master’s degree in Counselling Psychology from Assumption University in Thailand and began practising counselling in 2023. I am also a member of the Thailand Counseling Psychology Association (TCPA). Through my work, I have had the opportunity to support clients in individual, couples and group counselling, particularly with difficulties involving relationships, childhood trauma, attachment patterns and stress.

I have an especially personal understanding of international students and overseas Vietnamese because I have been through similar experiences and can relate to what you may be going through. I also understand those who are preparing for marriage, are married or have children, and can accompany you through these major milestones in life.

I have also helped facilitate group therapy at Horizon Rehab, including relapse-prevention programmes and art-based group therapy for people experiencing substance-use and mental health difficulties. At the same time, I have been with Wabi Therapy since its earliest days and continue to practise here today.

In counselling, I flexibly integrate Psychodynamic and Gestalt approaches, Cognitive Behavioural Therapy (CBT), Dialectical Behaviour Therapy (DBT), art-based therapy and other approaches. I do not believe that a single method suits everyone, because every client has their own story, pace and individual needs. What matters to me, therefore, is working with you to find the approach best suited to your journey.

My path into psychology also began with curiosity. Before receiving formal training in psychology, I explored Reiki (reaching Level I), Tarot, Oracle Cards—which I once incorporated into counselling alongside drawing—and natural healing practices. These experiences prompted many questions for me about people, emotions and the healing process, ultimately leading me toward a more scientific and professional engagement with psychology.

For me, counselling is not a place where you are “fixed,” but a space where you can slow down, be heard and look at yourself with curiosity rather than judgment. We talk together and explore what is on your mind. There is no need to rush; slowly and gently, we can begin to loosen the knots within. From there, you can understand yourself better, recognise what you truly need and discover more choices in how you want to live, love and connect with others.', null, null, true),
  (2, 'ThS. Ngọc Mai', 'Nguyễn Ngọc Mai', 'Xin chào, tôi là Ngọc Mai, Thạc sĩ Tâm lý học chuyên ngành Tâm lý lâm sàng và Cử nhân Tâm lý học chuyên ngành Tham vấn tâm lý tại Trường Đại học Khoa học Xã hội và Nhân văn, Đại học Quốc gia Hà Nội. Tôi bắt đầu thực hành tham vấn và trị liệu tâm lý từ năm 2020, và trong quá trình làm việc, tôi chủ yếu đồng hành cùng những người trẻ từ 18–35 tuổi đang tìm cách hiểu mình hơn, điều chỉnh cảm xúc, xây dựng những mối quan hệ lành mạnh và tìm kiếm một hướng đi phù hợp cho cuộc sống.

Tôi có kinh nghiệm đồng hành với những khó khăn liên quan đến tổn thương và trải nghiệm thời thơ ấu, căng thẳng, lo âu, trầm cảm, lòng tự trọng, tự chỉ trích, khủng hoảng và cảm giác mất phương hướng. Bên cạnh đó, tôi cũng làm việc với những vấn đề về gắn bó, các khuôn mẫu lặp lại trong tình yêu và các mối quan hệ gia đình, cũng như những áp lực trong học tập, công việc, định hướng nghề nghiệp và khủng hoảng sự nghiệp. Trong quá trình trị liệu, tôi linh hoạt kết hợp Trị liệu Nhân vị trọng tâm, Trị liệu Nhận thức Hành vi (CBT), Trị liệu Nhận thức Hành vi kết hợp Chánh niệm (MiCBT) và Hệ thống Gia đình Nội tâm (IFS), tùy thuộc vào nhu cầu, mục tiêu và nhịp độ riêng của từng thân chủ.

Tôi tin rằng bạn là người hiểu rõ nhất cuộc sống của mình và là người quyết định mình muốn đi về đâu. Nếu hành trình ấy giống như việc đi qua một đêm tối, tôi muốn mình giống như một chiếc đèn pin – không đi thay bạn, không quyết định con đường thay bạn, mà giúp bạn nhìn rõ hơn những gì đang ở phía trước.

Với tôi, tìm đến một nhà tâm lý không có nghĩa là bạn yếu đuối hay không thể tự giải quyết vấn đề. Đôi khi, đó chính là một cách để bạn dũng cảm đối diện với những điều mình đã cố gắng chịu đựng một mình quá lâu. Trị liệu không phải là hành trình để trở thành một con người hoàn toàn khác, mà là quá trình hiểu mình hơn, học cách chấp nhận cả những phần dễ tổn thương, tìm lại những nguồn lực vốn có và từng bước xây dựng một cuộc sống phù hợp hơn với chính mình. Tôi hy vọng quá trình đồng hành của chúng ta sẽ giúp bạn không chỉ vượt qua một giai đoạn khó khăn, mà còn dần học được cách trở thành người có thể lắng nghe, thấu hiểu và đồng hành cùng chính mình.', 'Hello, I’m Ngọc Mai. I hold a Master’s degree in Psychology, specialising in Clinical Psychology, and a Bachelor’s degree in Psychology, specialising in Counselling Psychology, from the University of Social Sciences and Humanities, Vietnam National University, Hanoi. I began practising counselling and psychotherapy in 2020. In my work, I primarily support young adults aged 18–35 who are seeking to understand themselves better, regulate their emotions, build healthy relationships and find a direction in life that feels right for them.

I have experience supporting people with difficulties related to childhood wounds and experiences, stress, anxiety, depression, self-esteem, self-criticism, crises and feeling lost. I also work with attachment concerns, recurring patterns in romantic and family relationships, and pressures related to study, work, career direction and career crises. In therapy, I flexibly integrate Person-Centred Therapy, Cognitive Behavioural Therapy (CBT), Mindfulness-integrated Cognitive Behaviour Therapy (MiCBT) and Internal Family Systems (IFS), depending on each client’s needs, goals and individual pace.

I believe that you understand your own life best and that you are the one who decides where you want to go. If that journey is like walking through a dark night, I would like to be like a flashlight for you—not to walk the journey or choose the path on your behalf, but to help illuminate what lies ahead.

To me, seeking support from a psychologist does not mean that you are weak or unable to solve your own problems. Sometimes, it is a way of courageously facing what you have tried to endure alone for too long. Therapy is not a journey toward becoming a completely different person; it is a process of understanding yourself more deeply, learning to accept your vulnerable parts, reconnecting with the resources already within you and gradually building a life that fits who you are. I hope our work together will help you not only move through a difficult period, but also gradually learn to become someone who can listen to, understand and support yourself.', null, null, true),
  (9, 'ThS. Minh Châu', 'Minh Châu', 'Xin chào, tôi là Minh Châu, Thạc sĩ Tâm lý học tại Trường Đại học Sư phạm Thành phố Hồ Chí Minh, với 7 năm kinh nghiệm thực hành trong lĩnh vực chăm sóc sức khỏe tâm thần. Trong quá trình làm việc, tôi có cơ hội đồng hành cùng nhiều thân chủ đang trải qua những khó khăn về lo âu, trầm cảm, đau buồn và mất mát, những vấn đề trong mối quan hệ gắn bó cũng như những ảnh hưởng còn kéo dài từ các trải nghiệm bất lợi thời thơ ấu.

Tôi đặc biệt quan tâm đến cách những trải nghiệm trong quá khứ có thể tiếp tục hiện diện trong đời sống hiện tại của mỗi người – qua cách chúng ta nhìn nhận bản thân, cảm nhận và điều hòa cảm xúc, xây dựng các mối quan hệ hay phản ứng trước những tình huống quen thuộc. Vì vậy, trong quá trình đồng hành, tôi không chỉ quan tâm đến điều đang khiến bạn khó khăn ở hiện tại, mà còn cùng bạn từ từ khám phá những câu chuyện, nhu cầu và trải nghiệm phía sau những điều ấy.

Về phương pháp, tôi thực hành theo hướng tích hợp, lấy nền tảng từ Phân tâm học (Psychoanalytic) và linh hoạt kết hợp các góc nhìn từ Tâm lý học Adler (Adlerian), thực hành Chú tâm (Mindfulness), sử dụng nghệ thuật như công cụ biểu đạt (art-based methods). Tôi tin rằng mỗi người có một câu chuyện riêng, vì vậy trị liệu cũng cần được điều chỉnh theo nhu cầu, khả năng và nhịp độ của từng thân chủ thay vì áp dụng một công thức giống nhau cho tất cả.

Với tôi, tham vấn tâm lý trước hết là một mối quan hệ an toàn, là không gian lắng nghe thấu đáo và không phán xét để bạn chậm lại, gọi tên và khám phá bất kỳ khía cạnh nào liên quan nhất đến sự an lành của mình — kể cả những bối rối hay nỗi đau sâu kín chưa thể gọi tên. Tôi mong muốn đồng hành cùng bạn để từng bước thấu hiểu, chấp nhận chính bản thân và sẵn sàng kết nối lành mạnh với cuộc sống.', 'Hello, I’m Minh Châu. I hold a Master’s degree in Psychology from Ho Chi Minh City University of Education and have seven years of practical experience in mental health care. In my work, I have had the opportunity to support many clients experiencing anxiety, depression, grief and loss, difficulties in attachment relationships, and the lasting effects of adverse childhood experiences.

I am especially interested in how past experiences can remain present in each person’s life today—through the ways we see ourselves, experience and regulate emotions, build relationships, or respond to familiar situations. In our work together, I therefore pay attention not only to what is causing you difficulty in the present, but also join you in gradually exploring the stories, needs and experiences behind it.

My practice is integrative, grounded in Psychoanalytic approaches and flexibly incorporating perspectives from Adlerian Psychology, Mindfulness practice and art-based methods as tools for expression. I believe that every person has their own story, so therapy needs to be adapted to each client’s needs, capacities and pace rather than following the same formula for everyone.

For me, psychological counselling is first and foremost a safe relationship: a space of attentive, non-judgmental listening where you can slow down, name and explore whatever feels most relevant to your well-being—including confusion or deeply held pain that cannot yet be named. I hope to accompany you as you gradually understand and accept yourself, and become ready to connect with life in healthier ways.', null, null, true),
  (4, 'ThS. Ly Đinh', 'Đinh Y Ly', 'Xin chào.

Tôi là Ly, là một thạc sĩ tâm lí (lâm sàng) được đào tạo từ trường ĐH KHXH&NV, ĐHQG Hà Nội với hơn 6 năm kinh nghiệm làm việc trong lĩnh vực tâm lí, bao gồm cung cấp dịch vụ đánh giá, tham vấn và trị liệu tâm lí cho các khách hàng cá nhân.

Từ những trải nghiệm cá nhân kết hợp với quá trình học tập, nghiên cứu và thực hành, tôi đã xác định và phát triển chuyên môn theo định hướng làm việc với các thân chủ là người trưởng thành mang những nỗi đau từ các trải nghiệm bất lợi, tổn thương, sang chấn thời thơ ấu. Các tổn thương đó có thể biểu hiện thành những rối loạn như trầm cảm, lo âu, cũng có thể ảnh hưởng đến lòng tự trọng, cách mỗi người nhìn nhận và đánh giá bản thân, lối hành xử và tương tác trong các mối quan hệ với người khác. Vì vậy, đây không phải một quá trình dễ dàng và nhanh chóng, nhưng tôi tin rằng mình đủ kiên nhẫn, kiến thức và trải nghiệm để đồng hành cùng bạn đi đến cuối hành trình khám phá và tự hàn gắn này.

Trong quá trình làm việc, tôi sử dụng kết hợp liệu pháp CBT với các triết lí và kĩ thuật về thân chủ trọng tâm, chánh niệm, chấp nhận và cam kết (ACT). Tuy vậy, đối với tôi, trị liệu tâm lí không chỉ là thực hành các liệu pháp hay kĩ thuật, mà đó là quá trình một người mở rộng vùng trải nghiệm của mình, thêm vào đó các trải nghiệm tích cực như được chấp nhận vô điều kiện, được lắng nghe, được nhìn thấy, được sự an toàn, được thử, được sai, được thử lại... Từ đó, bạn có thể dấn thân vào cuộc sống và các mối quan hệ, nhìn nhận các giá trị của bản thân, lấy lại sự tự chủ, tự do, niềm tin vào chính mình để hướng tới một cuộc sống bình an, độc lập.

Ngoài ra, tôi cũng đồng hành và hỗ trợ những người đang trải qua đau buồn và mất mát – dù đó là sự ra đi của người thân, thú cưng, chia tay mối quan hệ hay việc phải đối diện với bệnh tật và những thay đổi lớn trong cuộc sống. Đây đều là những trải nghiệm không dễ dàng, và bạn hoàn toàn có quyền lựa chọn không phải trải qua chúng một mình. Các phiên làm việc đều là không gian an toàn để bạn có thể từng bước nhìn nhận và xử lý những cảm xúc bạn đang trải qua, giải tỏa những điều còn dồn nén, thích nghi và dần tìm lại sự cân bằng trong cuộc sống.

Thực hành của tôi đều dựa trên các nguyên tắc đạo đức nghề nghiệp, sự tôn trọng và tin tưởng đối với mỗi thân chủ của mình. Mọi hoạt động hỗ trợ đều hướng đến lợi ích, nhu cầu và sự an toàn của chính bạn.', 'Hello.

I’m Ly. I hold a Master’s degree in Psychology, with a clinical focus, from the University of Social Sciences and Humanities, Vietnam National University, Hanoi. I have more than six years of experience in psychology, including providing psychological assessment, counselling and therapy services to individual clients.

Through my personal experiences alongside study, research and practice, I have shaped and developed my professional focus around working with adult clients who carry pain from adverse experiences, wounds and childhood trauma. These wounds may manifest as conditions such as depression and anxiety, and may also affect self-esteem, how a person sees and evaluates themselves, and how they behave and interact in relationships with others. This is therefore neither an easy nor a quick process, but I believe I have the patience, knowledge and experience to accompany you through to the end of this journey of exploration and self-healing.

In my work, I combine CBT with person-centred principles and techniques, mindfulness, and Acceptance and Commitment Therapy (ACT). For me, however, psychotherapy is not only about applying therapies or techniques. It is a process through which a person broadens their range of experience by making room for positive experiences: being accepted unconditionally, being heard, being seen, feeling safe, being allowed to try, to make mistakes and to try again... From there, you can engage more fully with life and relationships, recognise your own values, and regain autonomy, freedom and confidence in yourself as you move toward a peaceful, independent life.

I also accompany and support people experiencing grief and loss—whether the death of a loved one or pet, the end of a relationship, illness, or major changes in life. None of these experiences is easy, and you have every right to choose not to go through them alone. Each session is a safe space where you can gradually acknowledge and process the emotions you are experiencing, release what has remained pent up, adapt and slowly regain balance in your life.

My practice is grounded in professional ethical principles, as well as respect for and trust in every client. All support is centred on your own well-being, needs and safety.', null, null, true),
  (11, 'ThS. Quỳnh Trang', 'Ngọ Quỳnh Trang', 'Mình là Quỳnh Trang, Thạc sĩ Tâm lý học lâm sàng, chuyên ngành Tâm lý học lâm sàng Trẻ em và Vị thành niên, đồng thời có nền tảng Cử nhân Tâm lý học, chuyên ngành Tâm lý học Tham vấn. Trong 3 năm làm việc trong lĩnh vực tâm lý, mình có cơ hội đồng hành cùng nhiều thân chủ đang trải qua căng thẳng, lo âu, trầm cảm, những ảnh hưởng liên quan đến sang chấn và các khó khăn trong mối quan hệ cặp đôi. Mình đặc biệt quan tâm đến việc giúp thân chủ hiểu hơn về những gì đang diễn ra bên trong mình, thay vì chỉ cố gắng loại bỏ một triệu chứng hay giải quyết nhanh một vấn đề. Trong quá trình làm việc, mình lựa chọn cách tiếp cận dựa trên sự thấu cảm, tôn trọng và chấp nhận vô điều kiện theo tinh thần thân chủ trọng tâm. Tùy vào nhu cầu và mục tiêu của mỗi người, mình được đào tạo và ứng dụng Liệu pháp Nhận thức Hành vi (CBT), đồng thời tích hợp các kỹ thuật điều hòa cảm xúc từ Chánh niệm và Liệu pháp Chấp nhận và Cam kết (ACT). Mình tin rằng trị liệu không phải là nơi therapist đưa ra câu trả lời thay cho thân chủ, mà là một không gian đủ an toàn để thân chủ có thể chậm lại, nhìn lại và từng bước tìm ra câu trả lời phù hợp với chính mình. Có những lúc chúng ta cần một người đồng hành để hiểu điều gì đang xảy ra; có những lúc cần một người giúp mình học cách bước qua một đoạn đường khó; và cũng có lúc điều quan trọng nhất là nhận ra mình đã đủ vững vàng để tự bước tiếp.', 'I’m Quỳnh Trang. I hold a Master’s degree in Clinical Psychology, specialising in Child and Adolescent Clinical Psychology, as well as a Bachelor’s degree in Psychology, specialising in Counselling Psychology. During my three years working in psychology, I have had the opportunity to support many clients experiencing stress, anxiety, depression, trauma-related effects and difficulties in couple relationships. I am especially interested in helping clients understand more about what is happening within them, rather than simply trying to remove a symptom or quickly solve a problem. In my work, I take an approach grounded in empathy, respect and unconditional acceptance, in keeping with person-centred principles. Depending on each person’s needs and goals, I am trained in and apply Cognitive Behavioural Therapy (CBT), while also integrating emotion-regulation techniques from Mindfulness and Acceptance and Commitment Therapy (ACT). I believe therapy is not a place where the therapist gives clients answers, but a space safe enough for clients to slow down, reflect and gradually find answers that fit who they are. Sometimes we need a companion to help us understand what is happening; sometimes we need someone to help us learn how to make it through a difficult stretch of the road; and sometimes what matters most is recognising that we are steady enough to continue on our own.', 'Mình nghĩ bản thân giống như cây gậy, thân chủ có thể cần đến cây gậy để đi qua một đoạn đường dốc và trắc trở một cách vững vàng hơn, thân chủ cũng có thể dùng cây gậy để dò dẫm xem liệu con đường mình định bước có gì nguy hiểm không và đương nhiên, sẽ có đoạn đường, thân chủ không cần đến cây gậy nữa mà có thể tự đi một cách vững vàng, an toàn. Và mình ở đây, nếu bạn cần 1 chiếc gậy.', 'I think of myself as a walking stick. A client may need the stick to move more steadily through a steep and difficult stretch; they may also use it to feel out whether the path ahead holds any danger. And of course, there will come a part of the journey when they no longer need the stick and can walk on safely and steadily by themselves. I am here if you need a walking stick.', true),
  (5, 'ThS. Phương An', 'An Nguyễn Như Phương', 'Xin chào, tôi là Phương An, Thạc sĩ Tâm lý học Lâm sàng và Sức khỏe Tâm thần tại University of Sussex, Vương quốc Anh, và Cử nhân Tâm lý học tại Trường Đại học Sư phạm Hà Nội. Tôi có 4 năm kinh nghiệm trong lĩnh vực tâm lý học trường học, tham vấn và hỗ trợ sức khỏe tinh thần, với cơ hội đồng hành cùng trẻ em, thanh thiếu niên, người trưởng thành và gia đình trong nhiều bối cảnh khác nhau.

Trong công việc, tôi đặc biệt quan tâm đến những khó khăn liên quan đến lo âu, căng thẳng, điều chỉnh cảm xúc, lòng tự trọng, các mối quan hệ, học tập và quá trình thích nghi với những thay đổi trong cuộc sống. Bên cạnh việc đồng hành trực tiếp cùng thân chủ, tôi cũng hỗ trợ cha mẹ hiểu hơn về cảm xúc và hành vi của con, từ đó tìm ra những cách giao tiếp và đồng hành phù hợp hơn. Kinh nghiệm trong môi trường học đường giúp tôi nhìn nhận những khó khăn tâm lý trong mối liên hệ với nhiều yếu tố xung quanh một người, bao gồm gia đình, nhà trường và các mối quan hệ.

Trong tham vấn và trị liệu, tôi sử dụng Liệu pháp Nhận thức – Hành vi (CBT), Liệu pháp Chấp nhận và Cam kết (ACT), chánh niệm và một số kỹ thuật từ DBT. Tôi linh hoạt kết hợp các phương pháp dựa trên nhu cầu, mục tiêu và nhịp độ của từng thân chủ. Tôi tin rằng không có một công thức chung cho hành trình của mỗi người; điều quan trọng là cùng tìm ra một cách tiếp cận phù hợp và xây dựng một không gian đủ an toàn để thân chủ có thể thành thật với chính mình.

Tôi tin rằng mỗi người, dù là một đứa trẻ đang học cách gọi tên cảm xúc, một người trẻ đang loay hoay với những lựa chọn của mình, hay một người trưởng thành đang tìm lại hướng đi, đều xứng đáng được lắng nghe và thấu hiểu. Với tôi, trị liệu không phải là việc đưa ra câu trả lời thay bạn, mà là cùng bạn xây dựng một mối quan hệ đủ an toàn để bạn có thể là chính mình, hiểu bản thân sâu sắc hơn và từng bước tìm ra cách sống phù hợp với những điều thực sự có ý nghĩa với mình.', 'Hello, I’m Phương An. I hold a Master’s degree in Clinical Psychology and Mental Health from the University of Sussex in the United Kingdom, and a Bachelor’s degree in Psychology from Hanoi National University of Education. I have four years of experience in school psychology, counselling and mental health support, with opportunities to work alongside children, adolescents, adults and families across a range of settings.

In my work, I am especially interested in difficulties related to anxiety, stress, emotion regulation, self-esteem, relationships, learning and adapting to changes in life. Alongside working directly with clients, I also help parents better understand their children’s emotions and behaviours so they can find more suitable ways to communicate with and support them. My experience in school settings helps me understand psychological difficulties in relation to the many factors surrounding a person, including family, school and relationships.

In counselling and therapy, I use Cognitive Behavioural Therapy (CBT), Acceptance and Commitment Therapy (ACT), mindfulness and selected DBT techniques. I flexibly integrate these approaches according to each client’s needs, goals and pace. I believe there is no single formula for every person’s journey; what matters is finding a suitable approach together and building a space safe enough for clients to be honest with themselves.

I believe that everyone—whether a child learning to name their emotions, a young person wrestling with their choices, or an adult trying to find direction again—deserves to be heard and understood. For me, therapy is not about giving you answers, but about building a relationship with you that is safe enough for you to be yourself, understand yourself more deeply and gradually find a way of living aligned with what truly matters to you.', null, null, true),
  (7, 'ThS. Gia Bảo', 'Trần Gia Bảo', 'Xin chào, tôi là Gia Bảo, Thạc sĩ Tâm lý học tại Trường Đại học Giáo dục, Đại học Quốc gia Hà Nội, sau khi tốt nghiệp Cử nhân Tâm lý học tại Trường Đại học Sư phạm Hà Nội. Tôi có 4 năm kinh nghiệm trong lĩnh vực can thiệp các khó khăn và rối loạn hướng nội, đặc biệt là trầm cảm, lo âu và rối loạn nhân cách ranh giới. Bên cạnh thực hành, tôi cũng tham gia giảng dạy các khóa học chuyên môn về tâm lý học.

Trong quá trình làm việc, tôi sử dụng Liệu pháp Nhận thức Hành vi (CBT) làm phương pháp chính, kết hợp một số kỹ thuật từ Liệu pháp Hành vi Biện chứng (DBT) tùy theo nhu cầu và mục tiêu của từng thân chủ. Tôi tin rằng trị liệu không chỉ nhằm giảm bớt những triệu chứng đang gây khó khăn, mà còn giúp thân chủ hiểu mình hơn và từng bước có khả năng tự ứng phó với những thử thách trong cuộc sống.

Tôi tin rằng mục tiêu sâu xa nhất của trị liệu là giúp thân chủ trở thành chuyên gia tâm lý của chính mình – người có thể nhận biết, thấu hiểu và tự mình ứng phó với những khó khăn trong cuộc sống.

Vì vậy, tôi mong muốn tạo ra một không gian an toàn, nơi bạn có thể được lắng nghe và chia sẻ mà không sợ bị phán xét. Tôi sẽ cùng bạn khám phá những điều đang diễn ra, nhận diện nguồn lực của bản thân và từng bước tìm ra cách phù hợp để chăm sóc sức khỏe tinh thần của mình.', 'Hello, I’m Gia Bảo. I hold a Master’s degree in Psychology from the University of Education, Vietnam National University, Hanoi, after earning a Bachelor’s degree in Psychology from Hanoi National University of Education. I have four years of experience in interventions for internalising difficulties and disorders, particularly depression, anxiety and borderline personality disorder. Alongside my practice, I also teach professional courses in psychology.

In my work, I primarily use Cognitive Behavioural Therapy (CBT), integrating selected techniques from Dialectical Behaviour Therapy (DBT) according to each client’s needs and goals. I believe therapy is not only intended to ease symptoms that are causing difficulty, but also to help clients understand themselves better and gradually develop the ability to cope independently with life’s challenges.

I believe the deepest goal of therapy is to help clients become experts in their own psychological lives—able to recognise and understand their difficulties and cope with life’s challenges independently.

I therefore hope to create a safe space where you can be heard and share without fear of judgment. I will explore with you what is happening, help you recognise your own resources and gradually find suitable ways to care for your mental health.', null, null, true),
  (6, 'ThS. Kim Ngân', 'Nguyễn Thị Kim Ngân', 'Xin chào, tôi là Kim Ngân, Thạc sĩ Tâm lý học theo định hướng ứng dụng tại Trường Đại học Khoa học Xã hội và Nhân văn, Đại học Quốc gia Hà Nội, với 7 năm học tập và thực hành trong lĩnh vực sức khỏe tâm thần. Trong quá trình làm việc, tôi có cơ hội đồng hành cùng những người đang trải qua sang chấn, những trải nghiệm khó khăn thời thơ ấu và các vấn đề liên quan đến rối loạn cảm xúc như lo âu, trầm cảm, lưỡng cực, cũng như những khó khăn về giá trị bản thân, ranh giới, các mối quan hệ và sức khỏe sinh sản.

Tôi đặc biệt quan tâm đến cách những trải nghiệm trong quá khứ có thể để lại dấu ấn trong cách mỗi người nhìn nhận bản thân, cảm nhận cảm xúc và xây dựng mối quan hệ với những người xung quanh. Vì vậy, trong quá trình trị liệu, tôi mong muốn cùng thân chủ từ từ khám phá câu chuyện của chính mình, hiểu hơn về những điều đã hình thành nên con người hiện tại và tìm lại những nguồn lực bên trong để có thể sống theo cách phù hợp hơn với bản thân.

Trong thực hành, tôi sử dụng linh hoạt Liệu pháp Nhận thức Hành vi (CBT), Chánh niệm (Mindfulness) và Liệu pháp Hành vi Biện chứng (DBT), tùy thuộc vào nhu cầu, mục tiêu và nhịp độ của từng thân chủ. Với tôi, trị liệu không phải là một quá trình buộc chúng ta phải trở thành một phiên bản hoàn toàn khác, mà là cơ hội để hiểu mình sâu sắc hơn, học cách ở cùng những phần dễ tổn thương và từng bước xây dựng khả năng chăm sóc chính mình.

Tôi tin rằng mỗi người đều có khả năng hồi phục, ngay cả khi đang ở trong những giai đoạn khó khăn nhất. Tôi mong muốn tạo ra một không gian an toàn và đủ dịu dàng để bạn có thể được lắng nghe, được thấu hiểu và có thời gian phát triển theo nhịp độ của riêng mình. Có thể hành trình ấy bắt đầu từ một đêm tối, nhưng tôi tin rằng ở đâu đó bên trong mỗi người vẫn luôn có một hạt mầm đang chờ được chăm sóc để một ngày có thể nở hoa.', 'Hello, I’m Kim Ngân. I hold a practice-oriented Master’s degree in Psychology from the University of Social Sciences and Humanities, Vietnam National University, Hanoi, and have spent seven years studying and practising in the mental health field. In my work, I have had the opportunity to support people experiencing trauma, difficult childhood experiences and concerns related to emotional disorders such as anxiety, depression and bipolar disorder, as well as difficulties involving self-worth, boundaries, relationships and reproductive health.

I am especially interested in how past experiences can leave their mark on the way each person sees themselves, experiences emotions and builds relationships with those around them. In therapy, I therefore hope to join clients in gradually exploring their own stories, understanding more about what has shaped who they are today, and reconnecting with their inner resources so they can live in ways that fit them more closely.

In my practice, I flexibly use Cognitive Behavioural Therapy (CBT), Mindfulness and Dialectical Behaviour Therapy (DBT), depending on each client’s needs, goals and pace. For me, therapy is not a process that forces us to become a completely different version of ourselves, but an opportunity to understand ourselves more deeply, learn to be with our vulnerable parts and gradually build our capacity for self-care.

I believe everyone has the capacity to recover, even during the most difficult times. I hope to create a space that is safe and gentle enough for you to be heard and understood, and to have time to grow at your own pace. That journey may begin in darkness, but I believe that somewhere within each person there is always a seed waiting to be nurtured so that one day it can bloom.', 'Nảy mầm trong đêm tối và nở hoa dưới ánh mặt trời.', 'Sprouting in the darkness and blooming in the sunlight.', true)
) as v(expected_therapist_id, therapist_name, full_name, bio_vi, bio_en, quote_vi, quote_en, is_published)
join therapists t
  on t.id = v.expected_therapist_id and t.name = v.therapist_name
on conflict (therapist_id) do update set
  full_name = excluded.full_name,
  bio_vi = excluded.bio_vi,
  bio_en = excluded.bio_en,
  quote_vi = excluded.quote_vi,
  quote_en = excluded.quote_en,
  is_published = excluded.is_published,
  updated_at = now();
-- END GENERATED THERAPIST PROFILES
